(async () => {
      if (sessions.length === 0) {
        if (!cancelled) {
          setSummaries([]);
        }
        return;
      }

      try {
        const nextSummaries = await getOrgtrackSessionSummaries();
        if (!cancelled) {
          setSummaries(nextSummaries);
        }
      } catch (err) {
        logger.warn("failed to load orgtrack core summaries", { err });
      }
    })
